onClick:
{{(() => {
    // Use LocationManager validation
    const validation = LocationManager.validateOrderForm();

    if (!validation.isValid) {
        showAlert("Please fix the following errors:\n" + validation.errors.join("\n"), "error");
        return;
    }

    // Validate service rate selection
    if (!OrderShippingSelect.selectedOptionValue) {
        showAlert("Please select a delivery service (Standard or Express)", "error");
        return;
    }

    showAlert("Creating order...", "info");

    // One call now. The delivery quote used to be made here first, by two SQL
    // queries writing straight into the production database - and they reused a
    // single quote row for every order placed on the same rate within a day, then
    // never linked it to the order. Fulfilya builds the quote as it creates the
    // order, the same way it does for orders arriving from a shop.
    CreateOrderAPI.run()
        .then((result) => {
            const orderId = result.order_id || "New Order";

            showAlert(`Order ${orderId} created successfully`, "success");

            // Reset form using LocationManager
            LocationManager.resetOrderForm();

            closeModal('CreateOrderModal');

            // Refresh all dashboard data
            GetOrdersList.run();
            GetTotalOrders.run();
            GetOrdersByStatus.run();
            GetDailyOrders.run();
        })
        .catch(err => {
            console.error("Order creation failed:", err);
            // Fulfilya answers a rejected order with a sentence written for a
            // merchant to read - show that, not a status code.
            const reason = err.message || "Please check your input and try again";
            showAlert("Error creating order: " + reason, "error");
        });
})()}}
